/* ===== 微信礼物美化from 🍓小Q怡🍫 宝宝 ===== */
:root{
  --gift-card-bg-closed:  #004386;
  --gift-card-bg-opened:  #6085B2;
  --gift-text-color-closed: #F5D78A;
  --gift-text-color-opened: #DFC394;
  --gift-bow-closed: url('https://i.postimg.cc/05JwM20G/wu-biao-ti172-20260606010257.png');
  --gift-bow-opened: url('https://i.postimg.cc/ZYydBKx8/wu-biao-ti172-20260606010043.png');

  --bow-left: -12px;       /* 左右位置，数字越大越靠右 */
  --bow-top: 51%;         /* 上下位置，50% = 垂直居中 */
  --bow-offset-y: -65%;   /* 微调上下偏移 */
  --bow-size: 88px;       /* 蝴蝶结大小 */
  --gift-text-main:      "送你一份心意"; /*🎁备注*/
  --gift-text-opened:    "已收下";
  --gift-bottom-text:    "礼物";
}
@keyframes gift-sparkle-1{
  0%,100%{ opacity: 0; }
  50%{ opacity: 1; }
}
@keyframes gift-sparkle-2{
  0%,100%{ opacity: 0; }
  40%{ opacity: 0.8; }
  80%{ opacity: 0; }
}
@keyframes gift-sparkle-3{
  0%,100%{ opacity: 0; }
  30%{ opacity: 1; }
  70%{ opacity: 0.3; }
}
