/* 对方图片：去掉气泡 【不用改，样式容器隐藏用】 */
.msg-them:has(.msg-image-wrapper) .msg-bubble-container,
.msg-them:has(.msg-image-wrapper) .bubble-them-custom {
   background: transparent !important;
   border: none !important;
   box-shadow: none !important;
   padding: 0 !important;
}

/* ==========【修改图片最大尺寸、圆角 在这里！】========== */
/* 对方图片外层容器 */
.msg-them .msg-image-wrapper {
   /* 图片圆角值，改这里数字，8=8px圆角 */
   border-radius: 1px !important;
   overflow: hidden !important;
   border: none !important;
   box-shadow: none !important;
   background: transparent !important;
   position: relative !important;
   top: 0px !important;
   left: 0px !important;
   /* 图片最大宽度（横向上限） */
   max-width: 160px !important;
   /* 图片最大高度（纵向上限） */
   max-height: 200px !important;
   width: auto !important;
   height: auto !important;
}
/* 对方内部图片 圆角同步，改上面数字这里同步改即可 */
.msg-them .msg-image-wrapper img {
   width: 100% !important;
   height: auto !important;
   object-fit: cover !important;
   border-radius: 1px !important;
}

/* 我方图片外层容器 和上面对方参数完全一致，改这里同步尺寸圆角 */
.msg-me .msg-image-wrapper {
   /* 图片圆角 */
   border-radius: 1px !important;
   overflow: hidden !important;
   border: none !important;
   box-shadow: none !important;
   background: transparent !important;
   position: relative !important;
   top: 0px !important;
   left: 0px !important;
   /* 图片最大宽 */
   max-width: 160px !important;
   /* 图片最大高 */
   max-height: 200px !important;
   width: auto !important;
   height: auto !important;
}
/* 我方内部图片圆角 */
.msg-me .msg-image-wrapper img {
   width: 100% !important;
   height: auto !important;
   object-fit: cover !important;
   border-radius: 1px !important;
}
